<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Mockup — Solopreneur · Projects</title>
  <link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Crect x='2' y='2' width='20' height='20' rx='6' fill='none' stroke='%23c2009b' stroke-width='3'/%3E%3Crect x='7' y='7' width='6' height='6' rx='1.5' fill='%23c2009b'/%3E%3C/svg%3E" />
  <style>
    /* ============================================================
       1. TOKENS
       ============================================================ */
    *, *::before, *::after { box-sizing: border-box; }

    :root {
      --bg: #f5f5f6;
      --card: #ffffff;
      --line: #ececef;
      --line-2: #f1f1f4;
      --ink: #101014;
      --ink-2: #5e5e67;
      --ink-3: #94949c;
      --pink: #c2009b;
      --pink-2: #d6008f;
      --pink-ink: #a30080;
      --pink-soft: #fbe9f6;
      --green: #0d9a63;
      --green-soft: #e7f7ef;
      --amber: #9a5b00;
      --amber-soft: #fdf3e3;
      --danger: #c02626;
      --danger-soft: #fdecec;
      --black: #0b0b0e;
      --r-card: 16px;
      --r-md: 12px;
      --r-pill: 999px;
      --shadow: 0 1px 2px rgba(16, 16, 20, .04), 0 12px 28px rgba(16, 16, 20, .045);
      --fast: 150ms;
      --ease: cubic-bezier(.4, 0, .2, 1);
      --sidebar: 332px;
    }

    html, body { height: 100%; }
    body {
      margin: 0;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      font-size: 15px;
      background: var(--card);
      color: var(--ink);
      -webkit-font-smoothing: antialiased;
    }
    [hidden] { display: none !important; }
    button { font: inherit; color: inherit; cursor: pointer; }
    a { color: inherit; text-decoration: none; }
    :focus-visible { outline: 2px solid var(--pink); outline-offset: 2px; border-radius: 6px; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
    .muted { color: var(--ink-2); }
    .small { font-size: 13px; }

    /* ============================================================
       2. SHELL
       ============================================================ */
    .app { display: grid; grid-template-columns: var(--sidebar) minmax(0, 1fr); min-height: 100vh; background: var(--card); }
    .main { display: flex; flex-direction: column; min-width: 0; background: var(--bg); }

    .sidebar {
      background: var(--card);
      border-right: 1px solid var(--line);
      padding: 26px 22px 22px;
      display: flex; flex-direction: column;
      position: sticky; top: 0; height: 100vh;
    }
    .brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; margin-bottom: 40px; }
    .brand-name { font-size: 18px; font-weight: 600; letter-spacing: -.2px; }
    .side-user { display: flex; align-items: center; gap: 14px; padding: 0 6px; margin-bottom: 46px; }
    .avatar {
      width: 46px; height: 46px; border-radius: 50%; flex: 0 0 auto;
      display: grid; place-items: center; font-size: 14px; font-weight: 600; color: #fff;
      background: linear-gradient(145deg, #d0009f, #6f0057);
    }
    .side-user-txt { display: flex; flex-direction: column; min-width: 0; gap: 2px; }
    .side-user-txt strong { font-size: 15px; font-weight: 600; }
    .side-user-txt small { font-size: 13px; color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

    .nav { display: flex; flex-direction: column; gap: 2px; }
    .nav a {
      display: flex; align-items: center; gap: 16px;
      padding: 11px 14px; border-radius: var(--r-md);
      font-size: 15px; font-weight: 500; color: var(--ink);
      transition: background var(--fast) var(--ease);
    }
    .nav a:hover { background: #f7f7f9; }
    .nav a[aria-current="page"] { font-weight: 600; }
    .dot { width: 8px; height: 8px; border-radius: 50%; flex: 0 0 auto; background: #8d1158; opacity: .85; }
    .nav a[aria-current="page"] .dot { background: var(--pink); opacity: 1; }
    .dot-green { background: var(--green) !important; opacity: 1; }
    .dot-pink { background: var(--pink) !important; opacity: 1; }

    .side-foot { margin-top: auto; display: flex; flex-direction: column; gap: 14px; }
    .made { margin: 0 0 0 14px; font-size: 12.5px; color: var(--ink-3); }

    .topbar {
      position: sticky; top: 0; z-index: 20;
      display: flex; align-items: center; gap: 20px;
      padding: 18px 40px;
      background: var(--card);
      border-bottom: 1px solid var(--line);
    }
    .tb-title h1 { margin: 0; font-size: 20px; font-weight: 600; letter-spacing: -.2px; }
    .tb-title p { margin: 5px 0 0; font-size: 14.5px; color: var(--ink-2); }
    .topbar-actions { margin-left: auto; display: flex; align-items: center; gap: 12px; }

    .search-input {
      width: 264px; height: 44px; border-radius: var(--r-pill);
      border: 1px solid #e6e6ea; background: var(--card);
      padding: 0 20px; font: inherit; font-size: 14.5px; color: var(--ink);
    }
    .search-input::placeholder { color: var(--ink-3); }
    .search-input:focus { outline: none; border-color: var(--pink); box-shadow: 0 0 0 3px rgba(194, 0, 155, .12); }

    .btn {
      height: 44px; padding: 0 22px; border-radius: var(--r-pill);
      border: 1px solid transparent; font-size: 14.5px; font-weight: 600;
      display: inline-flex; align-items: center; justify-content: center; gap: 8px;
      transition: background var(--fast) var(--ease), transform var(--fast) var(--ease);
    }
    .btn:active { transform: scale(.985); }
    .btn-dark { background: var(--black); color: #fff; }
    .btn-dark:hover { background: #232329; }
    .btn-outline { background: var(--card); border-color: #e3e3e7; color: var(--ink); }
    .btn-outline:hover { background: #f7f7f9; }
    .btn-danger { background: var(--card); border-color: #ecc9c9; color: var(--danger); }
    .btn-danger:hover { background: var(--danger-soft); }
    .btn-sm { height: 36px; padding: 0 16px; font-size: 13.5px; }
    .btn[disabled] { opacity: .45; cursor: not-allowed; }

    /* ============================================================
       3. CONTENT
       ============================================================ */
    .content { padding: 24px 40px 56px; }
    .crumbs { display: flex; align-items: center; gap: 8px; font-size: 13.5px; color: var(--ink-3); margin-bottom: 18px; }
    .crumbs a { font-weight: 600; color: var(--ink-2); }
    .crumbs a:hover { color: var(--pink-ink); }

    .detail-head { display: flex; align-items: flex-start; gap: 20px; justify-content: space-between; margin-bottom: 26px; }
    .detail-head h1 { margin: 0; font-size: 26px; font-weight: 600; letter-spacing: -.5px; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
    .detail-head p { margin: 8px 0 0; font-size: 15px; color: var(--ink-2); max-width: 60ch; }

    .card {
      background: var(--card);
      border: 1px solid var(--line);
      border-radius: var(--r-card);
      box-shadow: var(--shadow);
      padding: 26px 28px;
      min-width: 0;
    }
    .card + .card { margin-top: 20px; }
    .card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
    .card h2 { margin: 0; font-size: 17px; font-weight: 600; letter-spacing: -.2px; }
    .card-desc { margin: 8px 0 0; font-size: 14.5px; line-height: 1.55; color: var(--ink-2); max-width: 62ch; }
    .link-accent { background: none; border: 0; padding: 0; font-size: 14px; font-weight: 600; color: var(--pink); }
    .link-accent:hover { text-decoration: underline; }

    .detail-grid { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 24px; align-items: start; }
    .col-main { display: flex; flex-direction: column; min-width: 0; }
    .col-side { position: sticky; top: 110px; }

    /* tabs */
    .tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--line); margin-bottom: 24px; }
    .tabs a {
      padding: 10px 16px; font-size: 14.5px; font-weight: 500; color: var(--ink-2);
      border-bottom: 2px solid transparent; margin-bottom: -1px;
    }
    .tabs a:hover { color: var(--ink); }
    .tabs a.is-on { color: var(--ink); font-weight: 600; border-bottom-color: var(--pink); }

    /* pills */
    .pill { font-size: 11.5px; font-weight: 600; padding: 4px 11px; border-radius: var(--r-pill); white-space: nowrap; }
    .pill-green { color: var(--green); background: var(--green-soft); }
    .pill-pink { color: var(--pink-ink); background: var(--pink-soft); }
    .pill-amber { color: var(--amber); background: var(--amber-soft); }
    .pill-grey { color: var(--ink-2); background: #f0f0f3; }

    /* banner */
    .banner {
      display: flex; align-items: center; gap: 20px; justify-content: space-between; flex-wrap: wrap;
      background: #fdf3fa; border: 1px solid #f3d9ec; border-radius: var(--r-card);
      padding: 20px 24px; margin-bottom: 20px;
    }
    .banner strong { font-size: 15.5px; font-weight: 600; }
    .banner p { margin: 4px 0 0; font-size: 14px; color: var(--ink-2); }

    /* chips */
    .chips { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 20px; }
    .chip {
      height: 36px; padding: 0 16px; border-radius: var(--r-pill);
      border: 1px solid #e6e6ea; background: var(--card);
      font-size: 13.5px; font-weight: 600; color: var(--ink-2);
      display: inline-flex; align-items: center; gap: 8px;
    }
    .chip:hover { background: #fafafa; }
    .chip.is-on { background: var(--black); border-color: var(--black); color: #fff; }
    .chip-count { font-size: 12px; opacity: .6; }

    /* project cards */
    .cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
    .p-card {
      background: var(--card); border: 1px solid var(--line); border-radius: var(--r-card);
      box-shadow: var(--shadow); padding: 22px; display: flex; flex-direction: column; min-width: 0;
    }
    .p-card-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
    .p-card-top h3 { margin: 0; font-size: 16.5px; font-weight: 600; letter-spacing: -.2px; }
    .p-card-desc { margin: 10px 0 0; font-size: 14px; line-height: 1.5; color: var(--ink-2); min-height: 42px; }
    .p-card-meta { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); }
    .p-card-need { display: flex; align-items: center; gap: 8px; margin: 14px 0 0; font-size: 12.5px; font-weight: 600; color: var(--pink-ink); }
    .p-card-foot { display: flex; gap: 10px; margin-top: 20px; }

    .progress { height: 6px; border-radius: var(--r-pill); background: #ececef; overflow: hidden; margin: 18px 0 0; }
    .progress i { display: block; height: 100%; border-radius: var(--r-pill); background: var(--pink-2); }

    /* needs block */
    .needs { display: flex; flex-direction: column; gap: 14px; margin-top: 20px; }
    .need {
      display: flex; align-items: center; justify-content: space-between; gap: 20px; flex-wrap: wrap;
      border: 1px solid #f3d9ec; background: #fdfbfd; border-radius: var(--r-md); padding: 18px 20px;
    }
    .need h3 { margin: 0; font-size: 15px; font-weight: 600; }
    .need p { margin: 5px 0 0; font-size: 13.5px; color: var(--ink-2); max-width: 52ch; }
    .need-actions { display: flex; gap: 10px; flex-wrap: wrap; }

    /* activity */
    .activity { list-style: none; margin: 22px 0 0; padding: 0; display: flex; flex-direction: column; gap: 20px; }
    .activity li { display: flex; gap: 14px; }
    .activity li > .dot { margin-top: 7px; }
    .activity p { margin: 0; font-size: 14.5px; line-height: 1.5; }
    .activity time { display: block; margin-top: 5px; font-size: 12px; color: var(--ink-3); }

    /* facts */
    .facts { margin: 22px 0 0; display: flex; flex-direction: column; gap: 16px; }
    .facts > div { display: flex; justify-content: space-between; gap: 16px; font-size: 14px; }
    .facts dt { margin: 0; color: var(--ink-2); }
    .facts dd { margin: 0; font-weight: 600; text-align: right; word-break: break-word; }

    /* sprint summary */
    .sprint-line { display: flex; align-items: center; gap: 14px; margin-top: 4px; }
    .sprint-line .progress { margin: 0; flex: 1; }
    .needs-note { margin: 16px 0 0; font-size: 13.5px; font-weight: 600; color: var(--pink-ink); }
    .card .btn { margin-top: 20px; }

    .table { width: 100%; border-collapse: collapse; font-size: 14px; margin-top: 18px; }
    .table th { text-align: left; font-size: 11.5px; letter-spacing: .07em; text-transform: uppercase; color: var(--ink-3); padding: 0 0 10px; font-weight: 600; }
    .table td { padding: 12px 0; border-top: 1px solid var(--line-2); }
    .table td:last-child, .table th:last-child { text-align: right; }

    /* forms */
    .form { display: flex; flex-direction: column; gap: 20px; }
    .field { display: flex; flex-direction: column; gap: 6px; }
    .field label { font-size: 13px; font-weight: 600; color: var(--ink-2); }
    .input {
      width: 100%; height: 44px; border-radius: var(--r-md);
      border: 1px solid #e3e3e7; padding: 0 14px;
      font: inherit; font-size: 14.5px; color: var(--ink); background: var(--card);
    }
    .input:focus { outline: none; border-color: var(--pink); box-shadow: 0 0 0 3px rgba(194, 0, 155, .12); }
    .input[aria-invalid="true"] { border-color: #e5a9a9; }
    textarea.input { height: auto; padding: 12px 14px; resize: vertical; line-height: 1.5; }
    .err { font-size: 12.5px; color: var(--danger); }
    .form-actions { display: flex; gap: 12px; flex-wrap: wrap; }
    .form-actions .btn { margin-top: 0; }

    .switch-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; padding: 4px 0; }
    .switch-row strong { font-size: 14.5px; font-weight: 600; }
    .switch-row p { margin: 4px 0 0; font-size: 13px; color: var(--ink-2); max-width: 44ch; }
    .switch {
      flex: 0 0 auto; width: 46px; height: 26px; border-radius: var(--r-pill);
      background: #e4e4e9; border: 0; position: relative;
      transition: background var(--fast) var(--ease);
    }
    .switch::after {
      content: ''; position: absolute; top: 3px; left: 3px; width: 20px; height: 20px;
      border-radius: 50%; background: #fff; transition: transform var(--fast) var(--ease);
    }
    .switch[aria-pressed="true"] { background: var(--pink-2); }
    .switch[aria-pressed="true"]::after { transform: translateX(20px); }

    .danger-zone { border-color: #f0dcdc; }
    .danger-zone h2 { color: var(--danger); }

    /* states */
    .empty { margin-top: 20px; padding: 44px 32px; text-align: center; font-size: 14.5px; color: var(--ink-2); background: #fafafb; border: 1px dashed #e2e2e6; border-radius: var(--r-md); }
    .empty .btn { margin-top: 18px; }
    .skeleton { border: 1px solid var(--line); border-radius: var(--r-card); background: linear-gradient(90deg, #f2f2f4 25%, #f9f9fa 37%, #f2f2f4 63%); background-size: 400% 100%; animation: shimmer 1.4s ease-in-out infinite; }
    @keyframes shimmer { 0% { background-position: 100% 0; } 100% { background-position: 0 0; } }
    .state-card { text-align: center; }
    .state-card .card-desc { margin-left: auto; margin-right: auto; }
    .state-card .btn { margin-top: 22px; }

    /* modals */
    .backdrop { position: fixed; inset: 0; z-index: 100; background: rgba(11, 11, 14, .42); }
    .dialog {
      position: fixed; z-index: 101; top: 50%; left: 50%; transform: translate(-50%, -50%);
      width: min(520px, calc(100vw - 32px)); max-height: calc(100vh - 64px); overflow: auto;
      background: var(--card); border-radius: 18px; padding: 26px;
      box-shadow: 0 24px 64px rgba(11, 11, 14, .28);
    }
    .dialog h2 { margin: 0 0 6px; font-size: 19px; font-weight: 600; }
    .dialog .sub { margin: 0 0 20px; font-size: 14px; color: var(--ink-2); }
    .dialog form { display: flex; flex-direction: column; gap: 16px; }
    .dialog-foot { display: flex; gap: 12px; justify-content: flex-end; margin-top: 8px; flex-wrap: wrap; }
    .dialog-foot .btn { margin-top: 0; }

    /* toasts */
    .toasts { position: fixed; right: 24px; bottom: 88px; z-index: 200; display: flex; flex-direction: column; gap: 10px; }
    .toast { background: var(--black); color: #fff; font-size: 14px; padding: 12px 18px; border-radius: var(--r-md); box-shadow: 0 12px 32px rgba(0, 0, 0, .28); animation: slide-in 220ms var(--ease); }
    .toast-error { background: var(--danger); }
    .toast.out { opacity: 0; transform: translateY(6px); transition: opacity 200ms var(--ease), transform 200ms var(--ease); }
    @keyframes slide-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

    /* dev panel */
    .dev { position: fixed; right: 24px; bottom: 24px; z-index: 300; font-size: 12.5px; }
    .dev-btn { background: var(--black); color: #fff; border: 0; border-radius: var(--r-pill); padding: 8px 14px; opacity: .3; }
    .dev:hover .dev-btn { opacity: 1; }
    .dev-body {
      position: absolute; right: 0; bottom: 44px; width: 220px;
      background: var(--card); border: 1px solid var(--line); border-radius: var(--r-md);
      box-shadow: var(--shadow); padding: 14px; display: flex; flex-direction: column; gap: 10px;
    }
    .dev-body label { display: flex; align-items: center; gap: 8px; cursor: pointer; }
    .dev-reset { background: none; border: 0; padding: 0; text-align: left; font-size: 12.5px; color: var(--pink); font-weight: 600; }

    /* ============================================================
       4. RESPONSIVE
       ============================================================ */
    @media (max-width: 1400px) {
      .cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .detail-grid { grid-template-columns: minmax(0, 1fr) 300px; }
    }
    @media (max-width: 1100px) {
      .detail-grid { grid-template-columns: minmax(0, 1fr); }
      .col-side { position: static; }
    }
    @media (max-width: 980px) {
      .app { grid-template-columns: 1fr; }
      .sidebar {
        position: sticky; height: auto; z-index: 30;
        flex-direction: row; align-items: center; gap: 12px;
        padding: 12px 16px; overflow-x: auto;
        border-right: 0; border-bottom: 1px solid var(--line);
      }
      .brand { margin: 0; }
      .brand-name, .side-user, .made { display: none; }
      .nav { flex-direction: row; gap: 2px; }
      .nav a { padding: 8px 10px; white-space: nowrap; }
      .side-foot { margin: 0; display: none; }
      .topbar { flex-wrap: wrap; padding: 16px; }
      .tb-title { flex: 1 1 100%; }
      .topbar-actions { width: 100%; justify-content: flex-end; flex-wrap: wrap; }
      .search-input { width: 180px; }
      .content { padding: 16px; }
      .cards { grid-template-columns: 1fr; }
      .card { padding: 20px; }
      .detail-head { flex-direction: column; }
    }
    @media (max-width: 560px) {
      .tabs { overflow-x: auto; }
      .need { flex-direction: column; align-items: flex-start; }
      .dialog { padding: 20px; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { transition: none !important; animation: none !important; }
    }
  </style>
</head>
<body>
  <div class="app">
    <aside class="sidebar" id="sidebar" aria-label="Main navigation"></aside>
    <div class="main">
      <header class="topbar" id="topbar"></header>
      <main class="content" id="view" role="main"></main>
    </div>
  </div>

  <div id="modal-root"></div>
  <div class="toasts" id="toasts" aria-live="polite" aria-atomic="false"></div>

  <div class="dev">
    <button class="dev-btn" type="button" data-action="dev-toggle">mock</button>
    <div class="dev-body" id="dev-body" hidden>
      <label><input type="checkbox" data-dev="slow" /> Slow network</label>
      <label><input type="checkbox" data-dev="fail" /> Force error</label>
      <label><input type="checkbox" data-dev="empty" /> Empty data</label>
      <button class="dev-reset" type="button" data-action="reset">Reset mock data</button>
    </div>
  </div>

  <script>
  (function () {
    'use strict';

    /* =========================================================
       A. CONFIG
       ========================================================= */
    const STORE_KEY = 'mock.codx.solopreneur.projects.v1';

    const NAV = [
      { id: 'summary',  label: 'Summary',  href: 'solopreneur.html#/solopreneur/summary' },
      { id: 'account',  label: 'Account',  href: 'solopreneur.html#/solopreneur/account' },
      { id: 'projects', label: 'Projects', href: 'solopreneur-projects.html#/projects' },
      { id: 'sprints',  label: 'Sprints',  href: 'solopreneur-sprints.html' },
      { id: 'wallet',   label: 'Wallet',   href: 'solopreneur.html#/solopreneur/wallet' },
      { id: 'updates',  label: 'Updates',  href: 'solopreneur.html#/solopreneur/updates' },
      { id: 'messages', label: 'Messages', href: 'solopreneur.html#/solopreneur/messages' }
    ];

    const TABS = [['overview', 'Overview'], ['sprints', 'Sprints'], ['settings', 'Settings']];

    const STATUS = {
      live:     ['Live', 'pill-green'],
      building: ['In progress', 'pill-pink'],
      paused:   ['Paused', 'pill-grey']
    };

    const ICONS = {
      logo: '<svg viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"><rect x="2.5" y="2.5" width="19" height="19" rx="5.5" fill="none" stroke="#c2009b" stroke-width="2.6"/><rect x="7" y="7" width="6" height="6" rx="1.6" fill="#c2009b"/></svg>'
    };

    /* =========================================================
       B. MOCK DATA (seed)
       ========================================================= */
    function seed() {
      return {
        user: {
          name: 'Sarah Denner', first: 'Sarah', initials: 'BB',
          email: 'sarah@bellaboutique.com'
        },
        sprints: [
          { id: 's_12', name: 'Sprint 12', range: '13 – 26 October', done: 3, total: 9, active: true, needs: 2 },
          { id: 's_11', name: 'Sprint 11', range: '29 September – 12 October', done: 8, total: 8, active: false, needs: 0 },
          { id: 's_10', name: 'Sprint 10', range: '15 – 28 September', done: 6, total: 7, active: false, needs: 0 }
        ],
        projects: [
          {
            id: 'p_1',
            name: 'Online store',
            status: 'live',
            summary: 'Your shop — customers browse, add to cart and pay.',
            about: 'This is the public shop. It takes orders, sends receipts, keeps stock in sync and tells you when something sells.',
            progress: 68,
            tasks: 12,
            updated: '2 h ago',
            url: 'bellaboutique.com',
            launched: 'March 2026',
            carer: 'Our AI, checked by María',
            auto: true,
            weekly: true,
            whoApproves: 'both',
            needs: [
              {
                id: 'a_1',
                title: 'Publish the new card payments',
                text: 'It is built and tested in test mode. It goes live as soon as you say yes.'
              }
            ],
            activity: [
              { id: 'x_1', text: 'Backup completed overnight. Nothing to do.', when: '2 h ago', tone: 'green' },
              { id: 'x_2', text: 'Product page now loads 40% faster.', when: 'Yesterday', tone: 'pink' },
              { id: 'x_3', text: 'Security scan passed, 6 packages updated.', when: 'Yesterday', tone: 'green' }
            ]
          },
          {
            id: 'p_2',
            name: 'Booking system',
            status: 'building',
            summary: 'Lets customers book a fitting or a visit.',
            about: 'Still being built. The calendar and the confirmation emails are the last pieces. Expect it live within two weeks.',
            progress: 45,
            tasks: 7,
            updated: 'Yesterday',
            url: 'not connected yet',
            launched: 'Not live yet',
            carer: 'Our AI, checked by María',
            auto: false,
            weekly: true,
            whoApproves: 'me',
            needs: [
              {
                id: 'a_2',
                title: 'Confirm your opening hours',
                text: 'We show available slots from them. Are they Monday to Saturday, 10:00 to 19:00?'
              }
            ],
            activity: [
              { id: 'x_4', text: 'Confirmation emails are ready to test.', when: 'Yesterday', tone: 'pink' },
              { id: 'x_5', text: 'Calendar screen finished on mobile.', when: '2 days ago', tone: 'green' }
            ]
          },
          {
            id: 'p_3',
            name: 'Company website',
            status: 'live',
            summary: 'The public site that tells people who you are.',
            about: 'Your front door. It shows the story, the opening hours and the address, and sends people to the shop.',
            progress: 90,
            tasks: 3,
            updated: '3 days ago',
            url: 'bellaboutique.com/about',
            launched: 'January 2026',
            carer: 'Our AI',
            auto: true,
            weekly: false,
            whoApproves: 'me',
            needs: [],
            activity: [
              { id: 'x_6', text: 'Opening hours updated for the winter.', when: '3 days ago', tone: 'green' }
            ]
          }
        ]
      };
    }

    /* =========================================================
       C. STATE
       ========================================================= */
    const state = {
      route: { name: 'list' },
      status: 'loading',
      data: seed(),
      ui: { query: '', filter: 'all', modal: null, errors: {} },
      dev: { slow: false, fail: false, empty: false }
    };

    /* =========================================================
       D. HELPERS
       ========================================================= */
    const byId = (id) => document.getElementById(id);
    const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

    function esc(value) {
      return String(value == null ? '' : value).replace(/[&<>"']/g, (c) => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
      }[c]));
    }

    function pill(status) {
      const cfg = STATUS[status] || STATUS.building;
      return '<span class="pill ' + cfg[1] + '">' + cfg[0] + '</span>';
    }

    function toast(message, kind) {
      const box = byId('toasts');
      const node = document.createElement('div');
      node.className = 'toast' + (kind === 'error' ? ' toast-error' : '');
      node.setAttribute('role', 'status');
      node.textContent = message;
      box.appendChild(node);
      setTimeout(() => {
        node.classList.add('out');
        setTimeout(() => node.remove(), 240);
      }, 3000);
    }

    /* =========================================================
       E. MOCK SERVER
       ========================================================= */
    const ROUTES = {
      'GET /api/projects': () => ({ projects: state.data.projects }),

      'POST /api/projects': (body) => {
        const name = String(body.name || '').trim();
        if (!name) throw new Error('invalid_name');
        const project = {
          id: 'p_' + Date.now(),
          name: name,
          status: 'building',
          summary: String(body.summary || '').trim() || 'New project — we are setting it up.',
          about: 'Just created. The first tasks appear here within a day, and you will get a note in Updates.',
          progress: 0,
          tasks: 0,
          updated: 'Just now',
          url: String(body.url || '').trim() || 'not connected yet',
          launched: 'Not live yet',
          carer: 'Our AI',
          auto: true,
          weekly: true,
          whoApproves: 'me',
          needs: [],
          activity: [{ id: 'x_new', text: 'Project created.', when: 'Just now', tone: 'pink' }]
        };
        state.data.projects.unshift(project);
        return { projects: state.data.projects, project: project };
      }
    };

    async function request(method, path, body) {
      await sleep(state.dev.slow ? 1200 : 170);
      if (state.dev.fail) throw new Error('server_error');

      const key = method + ' ' + path;
      if (ROUTES[key]) return ROUTES[key](body || {});

      let m = path.match(/^\/api\/projects\/([^/]+)$/);
      if (m) {
        const project = state.data.projects.find((p) => p.id === m[1]);
        if (!project) throw new Error('not_found');
        if (method === 'GET') return { project: project };
        if (method === 'PATCH') {
          Object.keys(body || {}).forEach((k) => { project[k] = body[k]; });
          project.updated = 'Just now';
          return { project: project };
        }
      }

      m = path.match(/^\/api\/projects\/([^/]+)\/needs\/([^/]+)\/approve$/);
      if (m && method === 'POST') {
        const project = state.data.projects.find((p) => p.id === m[1]);
        if (!project) throw new Error('not_found');
        const need = project.needs.find((n) => n.id === m[2]);
        project.needs = project.needs.filter((n) => n.id !== m[2]);
        project.progress = Math.min(100, project.progress + 4);
        project.activity.unshift({
          id: 'x_' + Date.now(),
          text: 'You approved: ' + (need ? need.title : 'a change') + '. It is live.',
          when: 'Just now',
          tone: 'green'
        });
        return { project: project };
      }

      throw new Error('not_found');
    }

    /* =========================================================
       F. ROUTING
       ========================================================= */
    function currentRoute() {
      const raw = location.hash.replace(/^#\/?/, '');
      const parts = raw.split('/').filter(Boolean);
      if (parts[0] !== 'projects' || !parts[1]) return { name: 'list' };
      return { name: 'detail', id: parts[1], tab: parts[2] || 'overview' };
    }

    async function navigate() {
      const route = currentRoute();
      state.route = route;
      state.status = 'loading';
      state.ui.errors = {};
      renderShell();
      renderView();
      try {
        if (route.name === 'list') {
          await request('GET', '/api/projects');
        } else {
          const res = await request('GET', '/api/projects/' + route.id);
          state.data.project = res.project;
        }
        state.status = 'ready';
      } catch (err) {
        state.status = 'error';
      }
      renderShell();
      renderView();
    }

    function onHashChange() {
      const route = currentRoute();
      if (route.name === 'detail' && state.route.name === 'detail' &&
          route.id === state.route.id && state.data.project) {
        state.route = route;
        renderView();
        return;
      }
      navigate();
    }

    /* =========================================================
       G. RENDER — shell
       ========================================================= */
    function renderShell() {
      byId('sidebar').innerHTML = sidebarHTML();
      byId('topbar').innerHTML = topbarHTML();
    }

    function sidebarHTML() {
      const u = state.data.user;
      const links = NAV.map((item) =>
        '<a href="' + item.href + '"' + (item.id === 'projects' ? ' aria-current="page"' : '') + '>' +
          '<span class="dot" aria-hidden="true"></span>' + esc(item.label) +
        '</a>'
      ).join('');

      return '' +
        '<div class="brand">' + ICONS.logo + '<span class="brand-name">codx-junior</span></div>' +
        '<div class="side-user">' +
          '<span class="avatar" aria-hidden="true">' + esc(u.initials) + '</span>' +
          '<div class="side-user-txt"><strong>' + esc(u.name) + '</strong><small>' + esc(u.email) + '</small></div>' +
        '</div>' +
        '<nav class="nav" aria-label="Solopreneur">' + links + '</nav>' +
        '<div class="side-foot"><p class="made">Make with ♡ by codx-junior</p></div>';
    }

    function topbarHTML() {
      const onDetail = state.route.name === 'detail' && state.data.project;
      const title = onDetail ? state.data.project.name : 'Projects';
      const sub = onDetail
        ? state.data.project.summary
        : 'Everything we build and run for you.';

      return '' +
        '<div class="tb-title"><h1>' + esc(title) + '</h1><p>' + esc(sub) + '</p></div>' +
        '<div class="topbar-actions">' +
          '<label class="sr-only" for="q">Search projects</label>' +
          '<input id="q" class="search-input" type="search" autocomplete="off" ' +
            'placeholder="Search..." value="' + esc(state.ui.query) + '" />' +
          '<button class="btn btn-dark" type="button" data-action="new-project">Add new project</button>' +
        '</div>';
    }

    /* =========================================================
       H. RENDER — list
       ========================================================= */
    function visibleProjects() {
      let list = state.dev.empty ? [] : state.data.projects.slice();
      const q = state.ui.query.trim().toLowerCase();
      if (q) {
        list = list.filter((p) => (p.name + ' ' + p.summary).toLowerCase().indexOf(q) >= 0);
      }
      const filter = state.ui.filter;
      if (filter === 'needs') list = list.filter((p) => p.needs.length > 0);
      else if (filter !== 'all') list = list.filter((p) => p.status === filter);
      return list;
    }

    function projectCard(p) {
      const needs = p.needs.length;
      return '' +
        '<article class="p-card">' +
          '<div class="p-card-top">' +
            '<h3>' + esc(p.name) + '</h3>' + pill(p.status) +
          '</div>' +
          '<p class="p-card-desc">' + esc(p.summary) + '</p>' +
          '<div class="progress"><i style="width:' + p.progress + '%"></i></div>' +
          '<p class="p-card-meta">' + p.progress + '% done · ' + p.tasks + ' tasks · updated ' + esc(p.updated) + '</p>' +
          (needs
            ? '<p class="p-card-need"><span class="dot dot-pink" aria-hidden="true"></span>' +
              needs + (needs === 1 ? ' thing' : ' things') + ' waiting for your OK</p>'
            : '') +
          '<div class="p-card-foot">' +
            '<a class="btn btn-dark btn-sm" href="#/projects/' + esc(p.id) + '/overview">Open</a>' +
            '<a class="btn btn-outline btn-sm" href="#/projects/' + esc(p.id) + '/settings">Settings</a>' +
          '</div>' +
        '</article>';
    }

    function listRegionHTML() {
      const all = state.dev.empty ? [] : state.data.projects;
      const needCount = all.reduce((n, p) => n + p.needs.length, 0);
      const list = visibleProjects();

      const chips = [
        ['all', 'All', all.length],
        ['live', 'Live', all.filter((p) => p.status === 'live').length],
        ['building', 'In progress', all.filter((p) => p.status === 'building').length],
        ['needs', 'Needs you', all.filter((p) => p.needs.length > 0).length]
      ];

      const banner = needCount
        ? '<div class="banner">' +
            '<div>' +
              '<strong>' + (needCount === 1 ? 'One thing needs your OK' : needCount + ' things need your OK') + '</strong>' +
              '<p>Approve them and your team keeps going. It takes about a minute.</p>' +
            '</div>' +
            '<button class="btn btn-dark btn-sm" type="button" data-action="filter" data-value="needs">Show me</button>' +
          '</div>'
        : '';

      const chipRow = '<div class="chips" role="group" aria-label="Filter projects">' +
        chips.map((c) =>
          '<button class="chip' + (state.ui.filter === c[0] ? ' is-on' : '') + '" type="button" ' +
            'data-action="filter" data-value="' + c[0] + '" aria-pressed="' + (state.ui.filter === c[0]) + '">' +
            esc(c[1]) + ' <span class="chip-count">' + c[2] + '</span>' +
          '</button>'
        ).join('') + '</div>';

      let body;
      if (list.length) {
        body = '<div class="cards">' + list.map(projectCard).join('') + '</div>';
      } else if (state.ui.query.trim()) {
        body = '<div class="empty">No project matches “' + esc(state.ui.query) + '”.</div>';
      } else {
        body = '<div class="empty">Nothing here yet.<br />' +
          '<button class="btn btn-dark" type="button" data-action="new-project">Add your first project</button></div>';
      }

      return banner + chipRow + body;
    }

    function viewList() {
      return '<div id="list-region">' + listRegionHTML() + '</div>';
    }

    /* =========================================================
       I. RENDER — detail
       ========================================================= */
    function viewDetail() {
      const p = state.data.project;
      if (!p) {
        return '<div class="card state-card"><h2>Project not found</h2>' +
          '<p class="card-desc">It may have been removed.</p>' +
          '<a class="btn btn-dark" href="#/projects">Back to projects</a></div>';
      }
      const tab = state.route.tab || 'overview';

      const tabs = TABS.map((t) =>
        '<a role="tab" href="#/projects/' + esc(p.id) + '/' + t[0] + '" ' +
          'aria-selected="' + (tab === t[0]) + '" class="' + (tab === t[0] ? 'is-on' : '') + '">' +
          esc(t[1]) + '</a>'
      ).join('');

      let panel;
      if (tab === 'sprints') panel = tabSprints();
      else if (tab === 'settings') panel = tabSettings(p);
      else panel = tabOverview(p);

      return '' +
        '<nav class="crumbs" aria-label="Breadcrumb">' +
          '<a href="#/projects">Projects</a><span aria-hidden="true">/</span>' +
          '<span aria-current="page">' + esc(p.name) + '</span>' +
        '</nav>' +
        '<div class="detail-head">' +
          '<div>' +
            '<h1>' + esc(p.name) + ' ' + pill(p.status) + '</h1>' +
            '<p>' + esc(p.summary) + '</p>' +
          '</div>' +
          '<a class="btn btn-dark" href="solopreneur-sprints.html">Open sprint board</a>' +
        '</div>' +
        '<div class="tabs" role="tablist" aria-label="Project sections">' + tabs + '</div>' +
        '<div class="detail-grid">' +
          '<div class="col-main">' + panel + '</div>' +
          '<div class="col-side">' + factsCard(p) + '</div>' +
        '</div>';
    }

    function tabOverview(p) {
      const needs = p.needs.length
        ? '<section class="card">' +
            '<h2>Waiting for you</h2>' +
            '<p class="card-desc">' +
              (p.needs.length === 1 ? 'One thing needs a quick OK.' : p.needs.length + ' things need a quick OK.') +
            '</p>' +
            '<div class="needs">' +
              p.needs.map((n) =>
                '<div class="need">' +
                  '<div>' +
                    '<h3>' + esc(n.title) + '</h3>' +
                    '<p>' + esc(n.text) + '</p>' +
                  '</div>' +
                  '<div class="need-actions">' +
                    '<button class="btn btn-dark btn-sm" type="button" data-action="approve" data-id="' + esc(n.id) + '">Approve</button>' +
                    '<button class="btn btn-outline btn-sm" type="button" data-action="ask" data-id="' + esc(n.id) + '">Ask a question</button>' +
                  '</div>' +
                '</div>'
              ).join('') +
            '</div>' +
          '</section>'
        : '';

      const activity = p.activity.map((a) =>
        '<li>' +
          '<span class="dot ' + (a.tone === 'green' ? 'dot-green' : 'dot-pink') + '" aria-hidden="true"></span>' +
          '<div><p>' + esc(a.text) + '</p><time>' + esc(a.when) + '</time></div>' +
        '</li>'
      ).join('');

      return '' +
        needs +
        '<section class="card">' +
          '<h2>What this is</h2>' +
          '<p class="card-desc">' + esc(p.about) + '</p>' +
        '</section>' +
        '<section class="card">' +
          '<div class="card-head"><h2>Recent activity</h2>' +
            '<span class="muted small">In plain words</span></div>' +
          '<ul class="activity">' + activity + '</ul>' +
        '</section>';
    }

    function tabSprints() {
      const current = state.data.sprints[0];
      const past = state.data.sprints.slice(1);
      const pct = Math.round((current.done / current.total) * 100);

      const rows = past.map((s) =>
        '<tr><td>' + esc(s.name) + '</td><td>' + esc(s.range) + '</td>' +
        '<td>' + s.done + ' of ' + s.total + ' done</td></tr>'
      ).join('');

      return '' +
        '<section class="card">' +
          '<div class="card-head">' +
            '<div>' +
              '<h2>' + esc(current.name) + '</h2>' +
              '<p class="card-desc">' + esc(current.range) + ' · the sprint we are working on right now.</p>' +
            '</div>' +
            '<span class="pill pill-pink">In progress</span>' +
          '</div>' +
          '<div class="sprint-line">' +
            '<div class="progress"><i style="width:' + pct + '%"></i></div>' +
            '<span class="muted small">' + current.done + ' of ' + current.total + ' done</span>' +
          '</div>' +
          (current.needs
            ? '<p class="needs-note">' + current.needs + ' tickets are waiting for your OK.</p>'
            : '') +
          '<a class="btn btn-dark" href="solopreneur-sprints.html">Open sprint board</a>' +
        '</section>' +
        '<section class="card">' +
          '<h2>Previous sprints</h2>' +
          '<table class="table">' +
            '<thead><tr><th>Sprint</th><th>Dates</th><th>Finished</th></tr></thead>' +
            '<tbody>' + rows + '</tbody>' +
          '</table>' +
        '</section>';
    }

    function tabSettings(p) {
      const err = state.ui.errors || {};

      return '' +
        '<form class="card form" data-form="settings" novalidate>' +
          '<div>' +
            '<h2>Project settings</h2>' +
            '<p class="card-desc">Everything here is simple and reversible.</p>' +
          '</div>' +
          '<div class="field">' +
            '<label for="s-name">Name</label>' +
            '<input class="input" id="s-name" name="name" value="' + esc(p.name) + '" ' +
              (err.name ? 'aria-invalid="true"' : '') + ' />' +
            (err.name ? '<span class="err">' + esc(err.name) + '</span>' : '') +
          '</div>' +
          '<div class="field">' +
            '<label for="s-url">Website address</label>' +
            '<input class="input" id="s-url" name="url" value="' + esc(p.url) + '" ' +
              (err.url ? 'aria-invalid="true"' : '') + ' />' +
            (err.url ? '<span class="err">' + esc(err.url) + '</span>' : '') +
          '</div>' +
          '<div class="switch-row">' +
            '<div>' +
              '<strong>Let us update this project automatically</strong>' +
              '<p>Small fixes and security updates happen without asking you.</p>' +
            '</div>' +
            '<button class="switch" type="button" data-action="toggle-setting" data-key="auto" ' +
              'aria-pressed="' + p.auto + '" aria-label="Automatic updates"></button>' +
          '</div>' +
          '<div class="switch-row">' +
            '<div>' +
              '<strong>Send me a weekly summary</strong>' +
              '<p>One short email every Monday. No noise in between.</p>' +
            '</div>' +
            '<button class="switch" type="button" data-action="toggle-setting" data-key="weekly" ' +
              'aria-pressed="' + p.weekly + '" aria-label="Weekly summary"></button>' +
          '</div>' +
          '<div class="field">' +
            '<label for="s-who">When something needs an OK, tell</label>' +
            '<select class="input" id="s-who" name="whoApproves">' +
              '<option value="me"' + (p.whoApproves === 'me' ? ' selected' : '') + '>Just me</option>' +
              '<option value="both"' + (p.whoApproves === 'both' ? ' selected' : '') + '>Me and my expert</option>' +
              '<option value="expert"' + (p.whoApproves === 'expert' ? ' selected' : '') + '>My expert only</option>' +
            '</select>' +
          '</div>' +
          '<div class="form-actions">' +
            '<button class="btn btn-dark" type="submit">Save changes</button>' +
            '<a class="btn btn-outline" href="#/projects/' + esc(p.id) + '/overview">Cancel</a>' +
          '</div>' +
        '</form>' +
        '<section class="card danger-zone">' +
          '<h2>Pause this project</h2>' +
          '<p class="card-desc">We stop all work and stop billing for it. Nothing is deleted, and you can start again whenever you want.</p>' +
          '<button class="btn btn-danger" type="button" data-action="pause">Pause project</button>' +
        '</section>';
    }

    function factsCard(p) {
      return '' +
        '<section class="card">' +
          '<h2>Key facts</h2>' +
          '<dl class="facts">' +
            '<div><dt>Website</dt><dd>' + esc(p.url) + '</dd></div>' +
            '<div><dt>Started</dt><dd>' + esc(p.launched) + '</dd></div>' +
            '<div><dt>Looked after by</dt><dd>' + esc(p.carer) + '</dd></div>' +
            '<div><dt>Updates</dt><dd>' + (p.auto ? 'Automatic' : 'With your OK') + '</dd></div>' +
            '<div><dt>Sprint</dt><dd><a class="link-accent" href="solopreneur-sprints.html">Open board</a></dd></div>' +
          '</dl>' +
        '</section>';
    }

    /* =========================================================
       J. RENDER — states
       ========================================================= */
    function viewSkeleton() {
      return '' +
        '<div style="height:34px"></div>' +
        '<div class="cards">' +
          '<div class="skeleton" style="height:250px"></div>' +
          '<div class="skeleton" style="height:250px"></div>' +
          '<div class="skeleton" style="height:250px"></div>' +
        '</div>';
    }

    function viewError() {
      return '' +
        '<section class="card state-card">' +
          '<h2>Something went wrong</h2>' +
          '<p class="card-desc">The mock server returned an error. Try again, or reload the page.</p>' +
          '<button class="btn btn-dark" type="button" data-action="retry">Try again</button>' +
        '</section>';
    }

    function renderView() {
      const host = byId('view');
      if (state.status === 'loading') { host.innerHTML = viewSkeleton(); return; }
      if (state.status === 'error') { host.innerHTML = viewError(); return; }
      host.innerHTML = state.route.name === 'detail' ? viewDetail() : viewList();
    }

    /* =========================================================
       K. RENDER — modals
       ========================================================= */
    function modalHTML() {
      const modal = state.ui.modal;
      if (!modal) return '';
      const err = state.ui.errors || {};

      if (modal.type === 'new') {
        return '' +
          '<h2 id="dialog-title">Add new project</h2>' +
          '<p class="sub">Three short questions. We do the rest.</p>' +
          '<form data-form="new" novalidate>' +
            '<div class="field">' +
              '<label for="m-name">Project name</label>' +
              '<input class="input" id="m-name" name="name" placeholder="e.g. Spring campaign" ' +
                (err.name ? 'aria-invalid="true"' : '') + ' />' +
              (err.name ? '<span class="err">' + esc(err.name) + '</span>' : '') +
            '</div>' +
            '<div class="field">' +
              '<label for="m-summary">What is it for?</label>' +
              '<input class="input" id="m-summary" name="summary" placeholder="One sentence in your own words" />' +
            '</div>' +
            '<div class="field">' +
              '<label for="m-url">Website address (optional)</label>' +
              '<input class="input" id="m-url" name="url" placeholder="yourbusiness.com" />' +
            '</div>' +
            '<div class="dialog-foot">' +
              '<button class="btn btn-outline" type="button" data-action="close-modal">Cancel</button>' +
              '<button class="btn btn-dark" type="submit">Create project</button>' +
            '</div>' +
          '</form>';
      }

      if (modal.type === 'ask') {
        const project = state.data.project;
        const need = project && project.needs.find((n) => n.id === modal.id);
        return '' +
          '<h2 id="dialog-title">Ask a question</h2>' +
          '<p class="sub">About: ' + esc(need ? need.title : 'this change') + '</p>' +
          '<form data-form="ask">' +
            '<div class="field">' +
              '<label for="m-ask">Your question</label>' +
              '<textarea class="input" id="m-ask" name="text" rows="4" placeholder="Type your question..."></textarea>' +
            '</div>' +
            '<div class="dialog-foot">' +
              '<button class="btn btn-outline" type="button" data-action="close-modal">Cancel</button>' +
              '<button class="btn btn-dark" type="submit">Send question</button>' +
            '</div>' +
          '</form>';
      }

      if (modal.type === 'pause') {
        return '' +
          '<h2 id="dialog-title">Pause this project?</h2>' +
          '<p class="sub">We stop working and stop billing. Nothing is deleted.</p>' +
          '<div class="dialog-foot">' +
            '<button class="btn btn-outline" type="button" data-action="close-modal">Keep it running</button>' +
            '<button class="btn btn-dark" type="button" data-action="confirm-pause">Pause project</button>' +
          '</div>';
      }

      return '';
    }

    function renderModal() {
      const root = byId('modal-root');
      const html = modalHTML();
      if (!html) {
        root.innerHTML = '';
        document.body.style.overflow = '';
        return;
      }
      root.innerHTML =
        '<div class="backdrop" data-action="close-modal"></div>' +
        '<div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title">' + html + '</div>';
      document.body.style.overflow = 'hidden';
      const target = root.querySelector('input, textarea, select, button');
      if (target) target.focus();
    }

    function openModal(type, id) {
      state.ui.modal = { type: type, id: id };
      renderModal();
    }

    function closeModal() {
      state.ui.modal = null;
      state.ui.errors = {};
      renderModal();
    }

    function render() {
      renderShell();
      renderView();
      renderModal();
    }

    /* =========================================================
       L. ACTIONS
       ========================================================= */
    async function createProject(data) {
      const name = String(data.name || '').trim();
      if (!name) {
        state.ui.errors = { name: 'Give the project a name.' };
        renderModal();
        return;
      }
      try {
        const res = await request('POST', '/api/projects', {
          name: name,
          summary: data.summary,
          url: data.url
        });
        closeModal();
        toast('Project created');
        location.hash = '#/projects/' + res.project.id + '/overview';
      } catch (err) {
        toast('Could not create the project. Try again.', 'error');
      }
    }

    async function approveNeed(id) {
      const project = state.data.project;
      if (!project) return;
      try {
        const res = await request('POST', '/api/projects/' + project.id + '/needs/' + id + '/approve');
        state.data.project = res.project;
        renderView();
        toast('Approved — your team is on it');
      } catch (err) {
        toast('Could not reach the server. Try again.', 'error');
      }
    }

    async function pauseProject() {
      const project = state.data.project;
      if (!project) return;
      try {
        const res = await request('PATCH', '/api/projects/' + project.id, { status: 'paused' });
        state.data.project = res.project;
        closeModal();
        render();
        toast('Project paused. Nothing was deleted.');
      } catch (err) {
        toast('Could not pause the project. Try again.', 'error');
      }
    }

    async function saveSettings(data) {
      const project = state.data.project;
      if (!project) return;

      const errors = {};
      if (!String(data.name || '').trim()) errors.name = 'Give the project a name.';
      if (!String(data.url || '').trim()) errors.url = 'Add the address, or write "not connected yet".';
      state.ui.errors = errors;

      if (Object.keys(errors).length) {
        renderView();
        toast('Please review the highlighted fields.', 'error');
        return;
      }

      try {
        const res = await request('PATCH', '/api/projects/' + project.id, {
          name: String(data.name).trim(),
          url: String(data.url).trim(),
          whoApproves: data.whoApproves
        });
        state.data.project = res.project;
        render();
        toast('Settings saved');
      } catch (err) {
        toast('Could not save. Try again.', 'error');
      }
    }

    function sendQuestion(data) {
      if (!String(data.text || '').trim()) {
        toast('Write your question first.', 'error');
        return;
      }
      closeModal();
      toast('Question sent — the answer shows up in Updates');
    }

    function toggleSetting(el) {
      const project = state.data.project;
      if (!project) return;
      const key = el.dataset.key;
      project[key] = !project[key];
      el.setAttribute('aria-pressed', String(project[key]));
    }

    function resetMock() {
      try { localStorage.removeItem(STORE_KEY); } catch (err) { /* ignore */ }
      state.data = seed();
      state.ui = { query: '', filter: 'all', modal: null, errors: {} };
      state.dev = { slow: false, fail: false, empty: false };
      const boxes = document.querySelectorAll('[data-dev]');
      boxes.forEach((b) => { b.checked = false; });
      toast('Mock data reset');
      navigate();
    }

    /* =========================================================
       M. PERSISTENCE
       ========================================================= */
    function persist() {
      try {
        localStorage.setItem(STORE_KEY, JSON.stringify({ data: state.data, filter: state.ui.filter }));
      } catch (err) { /* storage unavailable — mockup keeps working */ }
    }

    function hydrate() {
      try {
        const raw = localStorage.getItem(STORE_KEY);
        if (!raw) return;
        const parsed = JSON.parse(raw);
        if (parsed && parsed.data && parsed.data.projects) {
          state.data = parsed.data;
          state.ui.filter = parsed.filter || 'all';
        }
      } catch (err) { /* corrupt storage — fall back to seed */ }
    }

    /* =========================================================
       N. EVENTS
       ========================================================= */
    document.addEventListener('click', (e) => {
      const devBody = byId('dev-body');
      if (devBody && !e.target.closest('.dev')) devBody.hidden = true;

      const el = e.target.closest('[data-action]');
      if (!el) return;
      const action = el.dataset.action;

      switch (action) {
        case 'new-project':
          state.ui.errors = {};
          openModal('new');
          break;
        case 'filter':
          state.ui.filter = el.dataset.value;
          byId('list-region').innerHTML = listRegionHTML();
          persist();
          break;
        case 'approve':
          approveNeed(el.dataset.id);
          break;
        case 'ask':
          openModal('ask', el.dataset.id);
          break;
        case 'pause':
          openModal('pause');
          break;
        case 'confirm-pause':
          pauseProject();
          break;
        case 'toggle-setting':
          toggleSetting(el);
          break;
        case 'close-modal':
          closeModal();
          break;
        case 'dev-toggle':
          byId('dev-body').hidden = !byId('dev-body').hidden;
          break;
        case 'reset':
          resetMock();
          break;
        case 'retry':
          navigate();
          break;
        default:
          break;
      }
    });

    document.addEventListener('submit', (e) => {
      const form = e.target.closest('form[data-form]');
      if (!form) return;
      e.preventDefault();

      const kind = form.dataset.form;
      const data = {};
      new FormData(form).forEach((value, key) => { data[key] = value; });

      if (kind === 'new') createProject(data);
      if (kind === 'ask') sendQuestion(data);
      if (kind === 'settings') saveSettings(data);
    });

    document.addEventListener('input', (e) => {
      if (e.target.id !== 'q') return;
      state.ui.query = e.target.value;
      if (state.route.name !== 'list') {
        location.hash = '#/projects';
        return;
      }
      const region = byId('list-region');
      if (region) region.innerHTML = listRegionHTML();
    });

    document.addEventListener('change', (e) => {
      const dev = e.target.closest('[data-dev]');
      if (!dev) return;
      state.dev[dev.dataset.dev] = dev.checked;
      navigate();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      if (state.ui.modal) { closeModal(); return; }
      const devBody = byId('dev-body');
      if (devBody) devBody.hidden = true;
    });

    window.addEventListener('hashchange', onHashChange);
    window.addEventListener('beforeunload', persist);

    /* =========================================================
       O. BOOT
       ========================================================= */
    hydrate();
    if (!/^#\/projects/.test(location.hash)) {
      history.replaceState(null, '', '#/projects');
    }
    navigate();
  })();
  </script>
</body>
</html>
