<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Mockup — Solopreneur · Sprints</title>
  <link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'%3E%3Crect x='2' y='2' width='20' height='20' rx='6' fill='none' stroke='%23c2009b' stroke-width='3'/%3E%3Crect x='7' y='7' width='6' height='6' rx='1.5' fill='%23c2009b'/%3E%3C/svg%3E" />
  <style>
    /* ============================================================
       1. TOKENS
       ============================================================ */
    *, *::before, *::after { box-sizing: border-box; }

    :root {
      --bg: #f5f5f6;
      --card: #ffffff;
      --line: #ececef;
      --line-2: #f1f1f4;
      --ink: #101014;
      --ink-2: #5e5e67;
      --ink-3: #94949c;
      --pink: #c2009b;
      --pink-2: #d6008f;
      --pink-ink: #a30080;
      --pink-soft: #fbe9f6;
      --green: #0d9a63;
      --green-soft: #e7f7ef;
      --amber: #9a5b00;
      --amber-soft: #fdf3e3;
      --danger: #c02626;
      --black: #0b0b0e;
      --r-card: 16px;
      --r-md: 12px;
      --r-pill: 999px;
      --shadow: 0 1px 2px rgba(16, 16, 20, .04), 0 12px 28px rgba(16, 16, 20, .045);
      --fast: 150ms;
      --ease: cubic-bezier(.4, 0, .2, 1);
      --sidebar: 332px;
    }

    html, body { height: 100%; }
    body {
      margin: 0;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      font-size: 15px;
      background: var(--card);
      color: var(--ink);
      -webkit-font-smoothing: antialiased;
    }
    [hidden] { display: none !important; }
    button { font: inherit; color: inherit; cursor: pointer; }
    a { color: inherit; text-decoration: none; }
    :focus-visible { outline: 2px solid var(--pink); outline-offset: 2px; border-radius: 6px; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
    .muted { color: var(--ink-2); }
    .small { font-size: 13px; }

    /* ============================================================
       2. SHELL
       ============================================================ */
    .app { display: grid; grid-template-columns: var(--sidebar) minmax(0, 1fr); min-height: 100vh; background: var(--card); }
    .main { display: flex; flex-direction: column; min-width: 0; background: var(--bg); }

    .sidebar {
      background: var(--card);
      border-right: 1px solid var(--line);
      padding: 26px 22px 22px;
      display: flex; flex-direction: column;
      position: sticky; top: 0; height: 100vh;
    }
    .brand { display: flex; align-items: center; gap: 10px; padding: 0 6px; margin-bottom: 40px; }
    .brand-name { font-size: 18px; font-weight: 600; letter-spacing: -.2px; }
    .side-user { display: flex; align-items: center; gap: 14px; padding: 0 6px; margin-bottom: 46px; }
    .avatar {
      width: 46px; height: 46px; border-radius: 50%; flex: 0 0 auto;
      display: grid; place-items: center; font-size: 14px; font-weight: 600; color: #fff;
      background: linear-gradient(145deg, #d0009f, #6f0057);
    }
    .side-user-txt { display: flex; flex-direction: column; min-width: 0; gap: 2px; }
    .side-user-txt strong { font-size: 15px; font-weight: 600; }
    .side-user-txt small { font-size: 13px; color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

    .nav { display: flex; flex-direction: column; gap: 2px; }
    .nav a {
      display: flex; align-items: center; gap: 16px;
      padding: 11px 14px; border-radius: var(--r-md);
      font-size: 15px; font-weight: 500; color: var(--ink);
      transition: background var(--fast) var(--ease);
    }
    .nav a:hover { background: #f7f7f9; }
    .nav a[aria-current="page"] { font-weight: 600; }
    .dot { width: 8px; height: 8px; border-radius: 50%; flex: 0 0 auto; background: #8d1158; opacity: .85; }
    .nav a[aria-current="page"] .dot { background: var(--pink); opacity: 1; }
    .dot-green { background: var(--green) !important; opacity: 1; }
    .dot-pink { background: var(--pink) !important; opacity: 1; }

    .side-foot { margin-top: auto; }
    .made { margin: 0 0 0 14px; font-size: 12.5px; color: var(--ink-3); }

    .topbar {
      position: sticky; top: 0; z-index: 20;
