    .tb-title h1 { margin: 0; font-size: 20px; font-weight: 600; letter-spacing: -.2px; }
    .tb-title p { margin: 5px 0 0; font-size: 14.5px; color: var(--ink-2); }
    .topbar-actions { margin-left: auto; display: flex; align-items: center; gap: 12px; }

    .search-input {
      width: 264px; height: 44px; border-radius: var(--r-pill);
      border: 1px solid #e6e6ea; background: var(--card);
      padding: 0 20px; font: inherit; font-size: 14.5px; color: var(--ink);
    }
    .search-input::placeholder { color: var(--ink-3); }
    .search-input:focus { outline: none; border-color: var(--pink); box-shadow: 0 0 0 3px rgba(194, 0, 155, .12); }

    .btn {
      height: 44px; padding: 0 22px; border-radius: var(--r-pill);
      border: 1px solid transparent; font-size: 14.5px; font-weight: 600;
      display: inline-flex; align-items: center; justify-content: center; gap: 8px;
      transition: background var(--fast) var(--ease), transform var(--fast) var(--ease);
    }
    .btn:active { transform: scale(.985); }
    .btn-dark { background: var(--black); color: #fff; }
    .btn-dark:hover { background: #232329; }
    .btn-outline { background: var(--card); border-color: #e3e3e7; color: var(--ink); }
    .btn-outline:hover { background: #f7f7f9; }
    .btn-sm { height: 36px; padding: 0 16px; font-size: 13.5px; }
    .btn[disabled] { opacity: .45; cursor: not-allowed; }

    /* ============================================================
       3. CONTENT
       ============================================================ */
    .content { padding: 24px 40px 56px; }
    .crumbs { display: flex; align-items: center; gap: 8px; font-size: 13.5px; color: var(--ink-3); }
    .crumbs a { font-weight: 600; color: var(--ink-2); }
    .crumbs a:hover { color: var(--pink-ink); }

    .card {
      background: var(--card);
      border: 1px solid var(--line);
      border-radius: var(--r-card);
      box-shadow: var(--shadow);
      padding: 26px 28px;
      min-width: 0;
    }

    /* sprint header */
    .sprint-head { display: flex; flex-direction: column; gap: 22px; }
    .sprint-head-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 24px; flex-wrap: wrap; }
    .sprint-head h1 { margin: 10px 0 0; font-size: 26px; font-weight: 600; letter-spacing: -.5px; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
    .sprint-head .when { margin: 8px 0 0; font-size: 14.5px; color: var(--ink-2); }
    .sprint-select { display: flex; flex-direction: column; gap: 6px; }
    .sprint-select label { font-size: 12.5px; font-weight: 600; color: var(--ink-3); }

    .stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; }
    .stat { background: #f6f6f8; border-radius: var(--r-md); padding: 18px 20px; display: flex; flex-direction: column; gap: 4px; }
    .stat strong { font-size: 24px; font-weight: 600; letter-spacing: -.5px; }
    .stat span { font-size: 13px; color: var(--ink-2); }
    .stat.is-needs { background: var(--pink-soft); }
    .stat.is-needs strong { color: var(--pink-ink); }

    .progress { height: 6px; border-radius: var(--r-pill); background: #ececef; overflow: hidden; }
    .progress i { display: block; height: 100%; border-radius: var(--r-pill); background: var(--pink-2); }
    .progress.lg { height: 10px; }

    /* banner */
    .banner {
      display: flex; align-items: center; gap: 20px; justify-content: space-between; flex-wrap: wrap;
      background: #fdf3fa; border: 1px solid #f3d9ec; border-radius: var(--r-card);
      padding: 20px 24px; margin-top: 20px;
    }
    .banner strong { font-size: 15.5px; font-weight: 600; }
    .banner p { margin: 4px 0 0; font-size: 14px; color: var(--ink-2); }

    /* toolbar */
    .toolbar { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin: 24px 0 0; }
    .chips { display: flex; gap: 8px; flex-wrap: wrap; }
    .chip {
      height: 36px; padding: 0 16px; border-radius: var(--r-pill);
      border: 1px solid #e6e6ea; background: var(--card);
      font-size: 13.5px; font-weight: 600; color: var(--ink-2);
      display: inline-flex; align-items: center; gap: 8px;
    }
    .chip:hover { background: #fafafa; }
    .chip.is-on { background: var(--black); border-color: var(--black); color: #fff; }
    .chip-count { font-size: 12px; opacity: .6; }
    .toolbar .search-input { height: 36px; width: 240px; font-size: 13.5px; }

    /* board */
    .board { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; align-items: start; margin-top: 20px; }
    .col { background: #f7f7f9; border-radius: var(--r-card); padding: 16px; min-width: 0; }
    .col-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin: 0 4px 14px; }
    .col-head h2 { margin: 0; font-size: 13.5px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: var(--ink-2); }
    .col-head .count { font-size: 12px; font-weight: 600; color: var(--ink-3); background: #ececef; border-radius: var(--r-pill); padding: 2px 9px; }
    .col-empty { margin: 0 4px; font-size: 13px; color: var(--ink-3); padding: 10px 0 14px; }

    .ticket {
      background: var(--card); border: 1px solid var(--line); border-radius: 14px;
      box-shadow: 0 1px 2px rgba(16, 16, 20, .03); padding: 14px; margin-bottom: 12px;
    }
    .ticket:last-child { margin-bottom: 0; }
    .ticket-main { display: block; width: 100%; text-align: left; background: none; border: 0; padding: 0; }
    .ticket-main:hover .ticket-title { color: var(--pink-ink); }
    .ticket-flags { display: flex; align-items: center; gap: 8px; margin-bottom: 9px; }
    .ticket-due { font-size: 11.5px; color: var(--ink-3); margin-left: auto; white-space: nowrap; }
    .ticket-title { display: block; font-size: 14.5px; font-weight: 600; line-height: 1.42; letter-spacing: -.1px; }
    .ticket-foot { display: flex; align-items: center; gap: 10px; margin-top: 11px; font-size: 11.5px; color: var(--ink-3); }
    .who { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; color: var(--ink-2); font-size: 11.5px; }
    .who i {
      width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center;
      font-size: 9px; font-style: normal; font-weight: 700; color: #fff;
      background: linear-gradient(145deg, #d0009f, #6f0057);
    }
    .ticket-cta { width: 100%; margin-top: 12px; }

    /* pills */
    .pill { font-size: 11px; font-weight: 600; padding: 3px 10px; border-radius: var(--r-pill); white-space: nowrap; }
    .pill-green { color: var(--green); background: var(--green-soft); }
    .pill-pink { color: var(--pink-ink); background: var(--pink-soft); }
    .pill-amber { color: var(--amber); background: var(--amber-soft); }
    .pill-grey { color: var(--ink-2); background: #f0f0f3; }

    /* drawer */
    .drawer-backdrop { position: fixed; inset: 0; background: rgba(11, 11, 14, .36); z-index: 90; }
    .drawer {
      position: fixed; top: 0; right: 0; bottom: 0; z-index: 91;
      width: min(520px, 100vw); background: var(--card);
      box-shadow: -16px 0 48px rgba(11, 11, 14, .18);
      padding: 24px 28px 28px; overflow-y: auto;
      display: flex; flex-direction: column; gap: 18px;
    }
    .drawer-head { display: flex; align-items: center; gap: 10px; }
    .icon-btn {
      margin-left: auto; width: 36px; height: 36px; border-radius: 50%;
      border: 1px solid var(--line); background: var(--card); font-size: 15px; line-height: 1;
    }
    .icon-btn:hover { background: #f7f7f9; }
    .drawer h2 { margin: 0; font-size: 21px; font-weight: 600; letter-spacing: -.3px; line-height: 1.3; }
    .drawer-plain { margin: 0; font-size: 14.5px; line-height: 1.6; color: var(--ink-2); }
    .drawer .meta { display: flex; gap: 16px; flex-wrap: wrap; font-size: 12.5px; color: var(--ink-3); }

    .need-box { border: 1px solid #f3d9ec; background: #fdfbfd; border-radius: var(--r-md); padding: 18px 20px; }
    .need-box strong { display: block; font-size: 12px; letter-spacing: .07em; text-transform: uppercase; color: var(--pink-ink); }
    .need-box p { margin: 8px 0 0; font-size: 14px; line-height: 1.55; color: var(--ink); }
    .need-box .need-actions { display: flex; gap: 10px; margin-top: 16px; flex-wrap: wrap; }

    .seg-label { font-size: 12px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--ink-3); margin-bottom: 8px; }
    .seg { display: inline-flex; background: #f2f2f5; border-radius: var(--r-pill); padding: 4px; gap: 2px; }
    .seg button { border: 0; background: none; padding: 8px 15px; border-radius: var(--r-pill); font-size: 13.5px; font-weight: 600; color: var(--ink-2); }
    .seg button[aria-pressed="true"] { background: var(--card); color: var(--ink); box-shadow: 0 1px 3px rgba(16, 16, 20, .14); }

    .comments { display: flex; flex-direction: column; gap: 14px; }
    .comment { display: flex; gap: 10px; }
    .comment .who i { flex: 0 0 auto; }
    .comment div { min-width: 0; }
    .comment p { margin: 0; font-size: 14px; line-height: 1.5; }
    .comment time { display: block; margin-top: 4px; font-size: 11.5px; color: var(--ink-3); }
    .divider { height: 1px; background: var(--line); }

    .composer { display: flex; gap: 10px; margin-top: auto; position: sticky; bottom: -28px; background: var(--card); padding: 14px 0 0; }
    .composer input {
      flex: 1; min-width: 0; height: 44px; border-radius: var(--r-pill);
      border: 1px solid #e3e3e7; padding: 0 18px;
      font: inherit; font-size: 14px; color: var(--ink);
    }
    .composer input:focus { outline: none; border-color: var(--pink); box-shadow: 0 0 0 3px rgba(194, 0, 155, .12); }

    /* modals */
    .backdrop { position: fixed; inset: 0; z-index: 100; background: rgba(11, 11, 14, .42); }
    .dialog {
      position: fixed; z-index: 101; top: 50%; left: 50%; transform: translate(-50%, -50%);
      width: min(520px, calc(100vw - 32px)); max-height: calc(100vh - 64px); overflow: auto;
      background: var(--card); border-radius: 18px; padding: 26px;
      box-shadow: 0 24px 64px rgba(11, 11, 14, .28);
    }
    .dialog h2 { margin: 0 0 6px; font-size: 19px; font-weight: 600; }
    .dialog .sub { margin: 0 0 20px; font-size: 14px; color: var(--ink-2); }
    .dialog form { display: flex; flex-direction: column; gap: 16px; }
    .dialog-foot { display: flex; gap: 12px; justify-content: flex-end; margin-top: 8px; flex-wrap: wrap; }

    .field { display: flex; flex-direction: column; gap: 6px; }
    .field label { font-size: 13px; font-weight: 600; color: var(--ink-2); }
    .input {
      width: 100%; height: 44px; border-radius: var(--r-md);
      border: 1px solid #e3e3e7; padding: 0 14px;
      font: inherit; font-size: 14.5px; color: var(--ink); background: var(--card);
    }
    .input:focus { outline: none; border-color: var(--pink); box-shadow: 0 0 0 3px rgba(194, 0, 155, .12); }
    .input[aria-invalid="true"] { border-color: #e5a9a9; }
    textarea.input { height: auto; padding: 12px 14px; resize: vertical; line-height: 1.5; }
    .err { font-size: 12.5px; color: var(--danger); }

    /* states */
    .empty { margin-top: 20px; padding: 44px 32px; text-align: center; font-size: 14.5px; color: var(--ink-2); background: #fafafb; border: 1px dashed #e2e2e6; border-radius: var(--r-md); }
    .skeleton { border: 1px solid var(--line); border-radius: var(--r-card); background: linear-gradient(90deg, #f2f2f4 25%, #f9f9fa 37%, #f2f2f4 63%); background-size: 400% 100%; animation: shimmer 1.4s ease-in-out infinite; }
    @keyframes shimmer { 0% { background-position: 100% 0; } 100% { background-position: 0 0; } }
    .state-card { text-align: center; }
    .state-card .btn { margin-top: 22px; }

    /* toasts */
    .toasts { position: fixed; right: 24px; bottom: 88px; z-index: 200; display: flex; flex-direction: column; gap: 10px; }
    .toast { background: var(--black); color: #fff; font-size: 14px; padding: 12px 18px; border-radius: var(--r-md); box-shadow: 0 12px 32px rgba(0, 0, 0, .28); animation: slide-in 220ms var(--ease); }
    .toast-error { background: var(--danger); }
    .toast.out { opacity: 0; transform: translateY(6px); transition: opacity 200ms var(--ease), transform 200ms var(--ease); }
    @keyframes slide-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

    /* dev panel */
    .dev { position: fixed; right: 24px; bottom: 24px; z-index: 300; font-size: 12.5px; }
    .dev-btn { background: var(--black); color: #fff; border: 0; border-radius: var(--r-pill); padding: 8px 14px; opacity: .3; }
    .dev:hover .dev-btn { opacity: 1; }
    .dev-body {
      position: absolute; right: 0; bottom: 44px; width: 220px;
      background: var(--card); border: 1px solid var(--line); border-radius: var(--r-md);
      box-shadow: var(--shadow); padding: 14px; display: flex; flex-direction: column; gap: 10px;
    }
    .dev-body label { display: flex; align-items: center; gap: 8px; cursor: pointer; }
    .dev-reset { background: none; border: 0; padding: 0; text-align: left; font-size: 12.5px; color: var(--pink); font-weight: 600; }

    /* ============================================================
       4. RESPONSIVE
       ============================================================ */
    @media (max-width: 1200px) {
      .board { grid-template-columns: 1fr; }
      .stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }
    @media (max-width: 980px) {
      .app { grid-template-columns: 1fr; }
      .sidebar {
        position: sticky; height: auto; z-index: 30;
        flex-direction: row; align-items: center; gap: 12px;
        padding: 12px 16px; overflow-x: auto;
        border-right: 0; border-bottom: 1px solid var(--line);
      }
      .brand { margin: 0; }
      .brand-name, .side-user, .made { display: none; }
      .nav { flex-direction: row; gap: 2px; }
      .nav a { padding: 8px 10px; white-space: nowrap; }
      .side-foot { display: none; }
      .topbar { flex-wrap: wrap; padding: 16px; }
      .tb-title { flex: 1 1 100%; }
      .topbar-actions { width: 100%; justify-content: flex-end; flex-wrap: wrap; }
      .search-input { width: 180px; }
      .content { padding: 16px; }
      .card { padding: 20px; }
      .sprint-select { width: 100%; }
      .sprint-select select { width: 100%; }
      .toolbar .search-input { width: 100%; }
    }
    @media (max-width: 560px) {
      .stats { grid-template-columns: 1fr; }
      .drawer { padding: 20px; }
      .dialog { padding: 20px; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { transition: none !important; animation: none !important; }
    }
  </style>
</head>
<body>
  <div class="app">
    <aside class="sidebar" id="sidebar" aria-label="Main navigation"></aside>
    <div class="main">
      <header class="topbar" id="topbar"></header>
      <main class="content" id="view" role="main"></main>
    </div>
  </div>

  <div id="drawer-root"></div>
  <div id="modal-root"></div>
  <div class="toasts" id="toasts" aria-live="polite" aria-atomic="false"></div>

  <div class="dev">
    <button class="dev-btn" type="button" data-action="dev-toggle">mock</button>
    <div class="dev-body" id="dev-body" hidden>
      <label><input type="checkbox" data-dev="slow" /> Slow network</label>
      <label><input type="checkbox" data-dev="fail" /> Force error</label>
      <label><input type="checkbox" data-dev="empty" /> Empty data</label>
      <button class="dev-reset" type="button" data-action="reset">Reset mock data</button>
    </div>
  </div>

  <script>
  (function () {
    'use strict';

    /* =========================================================
       A. CONFIG
       ========================================================= */
    const STORE_KEY = 'mock.codx.solopreneur.sprints.v1';

    const NAV = [
      { id: 'summary',  label: 'Summary',  href: 'solopreneur.html#/solopreneur/summary' },
      { id: 'account',  label: 'Account',  href: 'solopreneur.html#/solopreneur/account' },
      { id: 'projects', label: 'Projects', href: 'solopreneur-projects.html#/projects' },
      { id: 'sprints',  label: 'Sprints',  href: 'solopreneur-sprints.html' },
      { id: 'wallet',   label: 'Wallet',   href: 'solopreneur.html#/solopreneur/wallet' },
      { id: 'updates',  label: 'Updates',  href: 'solopreneur.html#/solopreneur/updates' },
      { id: 'messages', label: 'Messages', href: 'solopreneur.html#/solopreneur/messages' }
    ];

    const COLUMNS = [
      ['todo', 'To do'],
      ['doing', 'In progress'],
      ['done', 'Done']
    ];

    const WHO = {
      ai:     ['AI', 'Our AI'],
      expert: ['MA', 'María (expert)'],
      you:    ['BB', 'You']
    };

    const ICONS = {
      logo: '<svg viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"><rect x="2.5" y="2.5" width="19" height="19" rx="5.5" fill="none" stroke="#c2009b" stroke-width="2.6"/><rect x="7" y="7" width="6" height="6" rx="1.6" fill="#c2009b"/></svg>'
    };

    /* =========================================================
       B. MOCK DATA (seed)
       ========================================================= */
    function seed() {
      return {
        user: { name: 'Sarah Denner', initials: 'BB', email: 'sarah@bellaboutique.com' },
        project: { id: 'p_1', name: 'Online store' },
        sprints: [
          {
            id: 's_12',
            name: 'Sprint 12',
            range: '13 – 26 October',
            daysLeft: 7,
            state: 'active',
            tickets: [
              {
                id: 't_1', title: 'Approve the new card payments', status: 'todo', who: 'expert',
                due: 'Today', needsYou: true,
                plain: 'We connected a card payment provider in test mode. Three test payments went through without a problem.',
                ask: 'Say yes and the shop can take cards tonight. Say no and we keep the current setup.',
                comments: [
                  { who: 'expert', text: 'Tested with 3 different cards. All good on our side.', when: '2 h ago' }
                ]
              },
              {
                id: 't_3', title: 'Confirm the shipping price for the new scarves', status: 'todo', who: 'you',
                due: 'Tomorrow', needsYou: true,
                plain: 'The courier charges €4.90 per parcel. We need to know what to charge customers.',
                ask: 'Approve €4.90, or leave a comment with the price you prefer.',
                comments: []
              },
              {
                id: 't_6', title: 'Add a size guide to every product', status: 'doing', who: 'ai',
                due: 'Thursday', needsYou: false,
                plain: 'A small size table opens from each product page. Half of the products already have it.',
                ask: '',
                comments: [
                  { who: 'ai', text: 'Done for the scarves and the coats. Tops next.', when: 'Yesterday' }
                ]
              },
              {
                id: 't_2', title: 'Fix the checkout button on mobile', status: 'doing', who: 'ai',
                due: 'Today', needsYou: false,
                plain: 'On phones the pay button was pushed below the screen and people could not find it. It is now at the top.',
                ask: '',
                comments: []
              },
              {
                id: 't_7', title: 'Rewrite the returns text in plain words', status: 'todo', who: 'expert',
                due: 'Next week', needsYou: false,
                plain: 'The current text is long and legal. We will shorten it to four clear lines.',
                ask: '',
                comments: []
              },
              {
                id: 't_8', title: 'Send the October newsletter', status: 'todo', who: 'you',
                due: 'Friday', needsYou: false,
                plain: 'The draft is ready with the new scarves. We wait for your go before sending it.',
                ask: '',
                comments: []
              },
              {
                id: 't_4', title: 'Speed up the product page', status: 'done', who: 'ai',
                due: '2 days ago', needsYou: false,
                plain: 'The page now loads in under a second on a normal phone. It was almost four seconds before.',
                ask: '',
                comments: []
              },
              {
                id: 't_5', title: 'Weekly backup check', status: 'done', who: 'ai',
                due: 'Yesterday', needsYou: false,
                plain: 'Backups ran every night. We restored one on a test copy and everything came back correctly.',
                ask: '',
                comments: []
              },
              {
                id: 't_9', title: 'Security updates', status: 'done', who: 'ai',
                due: '3 days ago', needsYou: false,
                plain: 'Six packages updated. No known issues are left open.',
                ask: '',
                comments: []
              }
            ]
          },
          {
            id: 's_11',
            name: 'Sprint 11',
            range: '29 September – 12 October',
            daysLeft: 0,
            state: 'closed',
            tickets: [
              {
                id: 'u_1', title: 'New product photos', status: 'done', who: 'expert', due: '12 Oct', needsYou: false,
                plain: 'All products now have clean photos on a white background.', ask: '',
                comments: []
              },
              {
                id: 'u_2', title: 'Fix the broken contact form', status: 'done', who: 'ai', due: '10 Oct', needsYou: false,
                plain: 'Messages were not arriving. They are now going to your inbox.', ask: '',
                comments: []
              },
              {
                id: 'u_3', title: 'Add the winter collection', status: 'done', who: 'expert', due: '6 Oct', needsYou: false,
                plain: 'Fourteen products were added with prices and sizes.', ask: '',
                comments: []
              },
              {
                id: 'u_4', title: 'Monthly security report', status: 'done', who: 'ai', due: '1 Oct', needsYou: false,
                plain: 'No issues found. Two packages updated.', ask: '',
                comments: []
              }
            ]
          }
        ]
      };
    }

    /* =========================================================
       C. STATE
       ========================================================= */
    const state = {
      status: 'loading',
      data: seed(),
      ui: { sprintId: 's_12', filter: 'all', query: '', openTicket: null, modal: null, errors: {} },
      dev: { slow: false, fail: false, empty: false }
    };

    /* =========================================================
       D. HELPERS
       ========================================================= */
    const byId = (id) => document.getElementById(id);
    const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

    function esc(value) {
      return String(value == null ? '' : value).replace(/[&<>"']/g, (c) => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
      }[c]));
    }

    function toast(message, kind) {
      const box = byId('toasts');
      const node = document.createElement('div');
      node.className = 'toast' + (kind === 'error' ? ' toast-error' : '');
      node.setAttribute('role', 'status');
      node.textContent = message;
      box.appendChild(node);
      setTimeout(() => {
        node.classList.add('out');
        setTimeout(() => node.remove(), 240);
      }, 3000);
    }

    function currentSprint() {
      const list = state.dev.empty ? [] : state.data.sprints;
      return list.find((s) => s.id === state.ui.sprintId) || list[0] || null;
    }

    function findTicket(id) {
      const sprint = currentSprint();
      if (!sprint) return null;
      return sprint.tickets.find((t) => t.id === id) || null;
    }

    function stats(sprint) {
      const tickets = sprint ? sprint.tickets : [];
      return {
        todo: tickets.filter((t) => t.status === 'todo').length,
        doing: tickets.filter((t) => t.status === 'doing').length,
        done: tickets.filter((t) => t.status === 'done').length,
        needs: tickets.filter((t) => t.needsYou).length,
        total: tickets.length
      };
    }

    /* =========================================================
       E. MOCK SERVER
       ========================================================= */
    const ROUTES = {
      'GET /api/sprints': () => ({ sprints: state.data.sprints }),

      'POST /api/tickets': (body) => {
        const sprint = currentSprint();
        if (!sprint) throw new Error('no_sprint');
        const title = String(body.title || '').trim();
        if (!title) throw new Error('invalid_title');
        const ticket = {
          id: 't_' + Date.now(),
          title: title,
          status: 'todo',
          who: 'you',
          due: 'To review',
          needsYou: false,
          plain: String(body.details || '').trim() || 'You asked for this. The team will look at it in the next sprint.',
          ask: '',
          comments: []
        };
        sprint.tickets.unshift(ticket);
        return { ticket: ticket };
      }
    };

    async function request(method, path, body) {
      await sleep(state.dev.slow ? 1200 : 170);
      if (state.dev.fail) throw new Error('server_error');

      const key = method + ' ' + path;
      if (ROUTES[key]) return ROUTES[key](body || {});

      let m = path.match(/^\/api\/tickets\/([^/]+)$/);
      if (m && method === 'PATCH') {
        const ticket = findTicket(m[1]);
        if (!ticket) throw new Error('not_found');
        if (body.status) ticket.status = body.status;
        return { ticket: ticket };
      }

      m = path.match(/^\/api\/tickets\/([^/]+)\/approve$/);
      if (m && method === 'POST') {
        const ticket = findTicket(m[1]);
        if (!ticket) throw new Error('not_found');
        ticket.needsYou = false;
        if (ticket.status === 'todo') ticket.status = 'doing';
        ticket.comments.push({ who: 'you', text: 'Approved.', when: 'Just now' });
        return { ticket: ticket };
      }

      m = path.match(/^\/api\/tickets\/([^/]+)\/comments$/);
      if (m && method === 'POST') {
        const ticket = findTicket(m[1]);
        if (!ticket) throw new Error('not_found');
        const text = String(body.text || '').trim();
        if (!text) throw new Error('empty_comment');
        ticket.comments.push({ who: 'you', text: text, when: 'Just now' });
        return { ticket: ticket };
      }

      throw new Error('not_found');
    }

    /* =========================================================
       F. RENDER — shell
       ========================================================= */
    function renderShell() {
      byId('sidebar').innerHTML = sidebarHTML();
      byId('topbar').innerHTML = topbarHTML();
    }

    function sidebarHTML() {
      const u = state.data.user;
      const links = NAV.map((item) =>
        '<a href="' + item.href + '"' + (item.id === 'sprints' ? ' aria-current="page"' : '') + '>' +
          '<span class="dot" aria-hidden="true"></span>' + esc(item.label) +
        '</a>'
      ).join('');

      return '' +
        '<div class="brand">' + ICONS.logo + '<span class="brand-name">codx-junior</span></div>' +
        '<div class="side-user">' +
          '<span class="avatar" aria-hidden="true">' + esc(u.initials) + '</span>' +
          '<div class="side-user-txt"><strong>' + esc(u.name) + '</strong><small>' + esc(u.email) + '</small></div>' +
        '</div>' +
        '<nav class="nav" aria-label="Solopreneur">' + links + '</nav>' +
        '<div class="side-foot"><p class="made">Make with ♡ by codx-junior</p></div>';
    }

    function topbarHTML() {
      return '' +
        '<div class="tb-title">' +
          '<h1>Sprints</h1>' +
          '<p>What is moving this week — only what needs you.</p>' +
        '</div>' +
        '<div class="topbar-actions">' +
          '<label class="sr-only" for="q">Search tickets</label>' +
          '<input id="q" class="search-input" type="search" autocomplete="off" ' +
            'placeholder="Search..." value="' + esc(state.ui.query) + '" />' +
          '<button class="btn btn-dark" type="button" data-action="new-ticket">Ask for something</button>' +
        '</div>';
    }

    /* =========================================================
       G. RENDER — view
       ========================================================= */
    function ticketCard(t) {
      const who = WHO[t.who] || WHO.ai;
      const comments = t.comments.length;
      return '' +
        '<article class="ticket">' +
          '<button class="ticket-main" type="button" data-action="open-ticket" data-id="' + esc(t.id) + '">' +
            '<span class="ticket-flags">' +
              (t.needsYou ? '<span class="pill pill-amber">Needs you</span>' : '') +
              '<span class="ticket-due">' + esc(t.due) + '</span>' +
            '</span>' +
            '<span class="ticket-title">' + esc(t.title) + '</span>' +
            '<span class="ticket-foot">' +
              '<span class="who"><i aria-hidden="true">' + esc(who[0]) + '</i>' + esc(who[1]) + '</span>' +
              (comments ? '<span>' + comments + (comments === 1 ? ' comment' : ' comments') + '</span>' : '') +
            '</span>' +
          '</button>' +
          (t.needsYou
            ? '<button class="btn btn-dark btn-sm ticket-cta" type="button" ' +
              'data-action="quick-approve" data-id="' + esc(t.id) + '">Approve</button>'
            : '') +
        '</article>';
    }

    function columnHTML(status, label, sprint) {
      const all = sprint ? sprint.tickets.filter((t) => t.status === status) : [];
      const list = visibleTickets(sprint).filter((t) => t.status === status);
      return '' +
        '<section class="col" aria-label="' + esc(label) + '">' +
