                  (active ? 'In progress' : 'Closed') + '</span>' +
              '</h1>' +
              '<p class="when">' + esc(sprint.range) +
                (active && sprint.daysLeft ? ' · ' + sprint.daysLeft + ' days left' : '') + '</p>' +
