    function viewSkeleton() {
      return '' +
        '<div class="skeleton" style="height:260px"></div>' +
        '<div class="board" style="margin-top:20px">' +
          '<div class="skeleton" style="height:300px"></div>' +
          '<div class="skeleton" style="height:220px"></div>' +
          '<div class="skeleton" style="height:180px"></div>' +
        '</div>';
    }

    function viewError() {
      return '<section class="card state-card">' +
        '<h2>Something went wrong</h2>' +
        '<p class="card-desc">The mock server returned an error. Try again, or reload the page.</p>' +
        '<button class="btn btn-dark" type="button" data-action="retry">Try again</button>' +
      '</section>';
    }

    function renderView() {
      const host = byId('view');
      if (state.status === 'loading') { host.innerHTML = viewSkeleton(); return; }
      if (state.status === 'error') { host.innerHTML = viewError(); return; }
      host.innerHTML = viewBoard();
    }

    /* =========================================================
       H. RENDER — drawer
       ========================================================= */
    function drawerHTML() {
      const t = state.ui.openTicket ? findTicket(state.ui.openTicket) : null;
      if (!t) return '';
      const who = WHO[t.who] || WHO.ai;
      const labels = { todo: 'To do', doing: 'In progress', done: 'Done' };

      const need = t.needsYou
        ? '<div class="need-box">' +
            '<strong>What we need from you</strong>' +
            '<p>' + esc(t.ask || 'A quick yes is enough.') + '</p>' +
            '<div class="need-actions">' +
              '<button class="btn btn-dark btn-sm" type="button" data-action="approve-ticket" data-id="' + esc(t.id) + '">Approve</button>' +
              '<button class="btn btn-outline btn-sm" type="button" data-action="focus-comment">Ask a question</button>' +
            '</div>' +
          '</div>'
        : '';

      const seg = COLUMNS.map((c) =>
        '<button type="button" data-action="move" data-id="' + esc(t.id) + '" data-status="' + c[0] + '" ' +
