      return '' +
        '<div class="drawer-backdrop" data-action="close-ticket"></div>' +
        '<aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="ticket-title">' +
          '<div class="drawer-head">' +
            (t.needsYou ? '<span class="pill pill-amber">Needs you</span>' : '<span class="pill pill-grey">' + labels[t.status] + '</span>') +
            '<button class="icon-btn" type="button" data-action="close-ticket" aria-label="Close">✕</button>' +
          '</div>' +
          '<h2 id="ticket-title">' + esc(t.title) + '</h2>' +
          '<div class="meta">' +
            '<span class="who"><i aria-hidden="true">' + esc(who[0]) + '</i>' + esc(who[1]) + '</span>' +
            '<span>' + esc(t.due) + '</span>' +
          '</div>' +
          '<p class="drawer-plain">' + esc(t.plain) + '</p>' +
