      if (modal.type === 'new-ticket') {
        return '' +
          '<h2 id="dialog-title">Ask for something</h2>' +
          '<p class="sub">Tell us in your own words. It lands in the next sprint.</p>' +
          '<form data-form="new-ticket" novalidate>' +
            '<div class="field">' +
              '<label for="m-title">What do you need?</label>' +
              '<input class="input" id="m-title" name="title" placeholder="e.g. Add gift wrapping to the shop" ' +
