                'placeholder="Prices, dates, links... whatever you have"></textarea>' +
            '</div>' +
            '<div class="dialog-foot">' +
              '<button class="btn btn-outline" type="button" data-action="close-modal">Cancel</button>' +
              '<button class="btn btn-dark" type="submit">Send request</button>' +
            '</div>' +
          '</form>';
      }

      return '';
    }

    function renderModal() {
      const root = byId('modal-root');
      const html = modalHTML();
      root.innerHTML = html
        ? '<div class="backdrop" data-action="close-modal"></div>' +
          '<div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title">' + html + '</div>'
        : '';
      if (html) {
        const target = root.querySelector('input, textarea, button');
        if (target) target.focus();
      }
    }

    /* =========================================================
       J. ACTIONS
       ========================================================= */
    async function load() {
      state.status = 'loading';
      renderShell();
      renderView();
      try {
        await request('GET', '/api/sprints');
        state.status = 'ready';
      } catch (err) {
        state.status = 'error';
      }
      renderShell();
      renderView();
    }

    async function approveTicket(id) {
      try {
        await request('POST', '/api/tickets/' + id + '/approve');
        renderView();
        renderDrawer();
        toast('Approved — your team is on it');
      } catch (err) {
        toast('Could not approve. Try again.', 'error');
      }
    }

    async function moveTicket(id, status) {
      try {
        await request('PATCH', '/api/tickets/' + id, { status: status });
        renderView();
        renderDrawer();
        toast('Moved');
      } catch (err) {
        toast('Could not move the ticket. Try again.', 'error');
      }
    }

    async function addComment(text) {
      const id = state.ui.openTicket;
      if (!id || !String(text || '').trim()) return;
      try {
        await request('POST', '/api/tickets/' + id + '/comments', { text: text });
        renderView();
        renderDrawer();
      } catch (err) {
        toast('Could not send the comment. Try again.', 'error');
      }
    }

    async function createTicket(data) {
      const title = String(data.title || '').trim();
      if (!title) {
        state.ui.errors = { title: 'Tell us what you need.' };
        renderModal();
        return;
      }
      try {
        await request('POST', '/api/tickets', { title: title, details: data.details });
        state.ui.modal = null;
        state.ui.errors = {};
        renderModal();
        renderView();
        toast('Request added to the sprint');
      } catch (err) {
        toast('Could not send the request. Try again.', 'error');
      }
    }

    function resetMock() {
      try { localStorage.removeItem(STORE_KEY); } catch (err) { /* ignore */ }
      state.data = seed();
      state.ui = { sprintId: 's_12', filter: 'all', query: '', openTicket: null, modal: null, errors: {} };
      state.dev = { slow: false, fail: false, empty: false };
      document.querySelectorAll('[data-dev]').forEach((b) => { b.checked = false; });
      toast('Mock data reset');
      load();
    }

    /* =========================================================
       K. PERSISTENCE
       ========================================================= */
    function persist() {
      try {
        localStorage.setItem(STORE_KEY, JSON.stringify({
          data: state.data,
          sprintId: state.ui.sprintId,
          filter: state.ui.filter
        }));
      } catch (err) { /* storage unavailable — mockup keeps working */ }
    }

    function hydrate() {
      try {
        const raw = localStorage.getItem(STORE_KEY);
        if (!raw) return;
        const parsed = JSON.parse(raw);
        if (parsed && parsed.data && parsed.data.sprints && parsed.data.sprints.length) {
          state.data = parsed.data;
          state.ui.sprintId = parsed.sprintId || state.data.sprints[0].id;
          state.ui.filter = parsed.filter || 'all';
        }
      } catch (err) { /* corrupt storage — fall back to seed */ }
    }

    /* =========================================================
       L. EVENTS
       ========================================================= */
    document.addEventListener('click', (e) => {
      const devBody = byId('dev-body');
      if (devBody && !e.target.closest('.dev')) devBody.hidden = true;

      const el = e.target.closest('[data-action]');
      if (!el) return;
      const action = el.dataset.action;

      switch (action) {
        case 'open-ticket':
          state.ui.openTicket = el.dataset.id;
          renderDrawer();
          break;
        case 'close-ticket':
          state.ui.openTicket = null;
          renderDrawer();
          break;
        case 'quick-approve':
          approveTicket(el.dataset.id);
          break;
        case 'approve-ticket':
          approveTicket(el.dataset.id);
          break;
        case 'focus-comment': {
          const input = byId('comment-input');
          if (input) input.focus();
          break;
        }
        case 'move':
          moveTicket(el.dataset.id, el.dataset.status);
          break;
        case 'filter':
          state.ui.filter = el.dataset.value;
          renderView();
          persist();
          break;
        case 'new-ticket':
          state.ui.errors = {};
          state.ui.modal = { type: 'new-ticket' };
          renderModal();
          break;
        case 'close-modal':
          state.ui.modal = null;
          state.ui.errors = {};
          renderModal();
          break;
        case 'dev-toggle':
          byId('dev-body').hidden = !byId('dev-body').hidden;
          break;
        case 'reset':
          resetMock();
          break;
        case 'retry':
          load();
          break;
        default:
          break;
      }
    });

    document.addEventListener('submit', (e) => {
      const form = e.target.closest('form[data-form]');
      if (!form) return;
      e.preventDefault();

      const kind = form.dataset.form;
      const data = {};
      new FormData(form).forEach((value, key) => { data[key] = value; });

      if (kind === 'comment') {
        const input = form.querySelector('input');
        const text = input ? input.value : '';
        if (input) input.value = '';
        addComment(text);
        return;
      }
      if (kind === 'new-ticket') createTicket(data);
    });

    document.addEventListener('input', (e) => {
      if (e.target.id !== 'q') return;
      state.ui.query = e.target.value;
      renderView();
    });

    document.addEventListener('change', (e) => {
      if (e.target.id === 'sprint-select') {
        state.ui.sprintId = e.target.value;
        state.ui.openTicket = null;
        renderDrawer();
        renderView();
        persist();
        return;
      }
      const dev = e.target.closest('[data-dev]');
      if (dev) {
        state.dev[dev.dataset.dev] = dev.checked;
        load();
      }
    });

    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      if (state.ui.modal) { state.ui.modal = null; renderModal(); return; }
      if (state.ui.openTicket) { state.ui.openTicket = null; renderDrawer(); return; }
      const devBody = byId('dev-body');
      if (devBody) devBody.hidden = true;
    });

    window.addEventListener('beforeunload', persist);

    /* =========================================================
       M. BOOT
       ========================================================= */
    hydrate();
    load();
  })();
  </script>
</body>
</html>
