function submitProject() {
  createProject({ name: name.value, repo: repo.value })
}

function submitCredits() { addCredits(pack.value) }
function submitPlan() { changePlan(plan.value) }

function messageTeam() {
  closeModal()
  goModule('messages')
}
</script>

