}

async function openSettings(id) {
  await selectProject(id)
  setTab('settings')
}

// ── new project dialog ──────────────────────────────────────────────────────
const showNewProject = ref(false)
const newName = ref('')
const newRepo = ref('')

function openNewProject() {
  newName.value = ''
  newRepo.value = ''
  ui.errors = {}
  showNewProject.value = true
}

function closeNewProject() {
  showNewProject.value = false
  ui.errors = {}
}

